before:
Complete local Rust example; the app itself does not execute it:
```rust
trait Label { fn label(&self) -> &str; }
struct Topic(String);
impl Label for Topic {
    fn label(&self) -> &str { &self.0 }
}
fn main() {
    let topic = Topic(String::from("Rust"));
    println!("{}", topic.label());
}
```

